		return 1
	}
	// Find all divisors of A
	divisors := getDivisors(A)
	count := 0
	for _, d := range divisors {
		if d == A {
			continue
		}
		// Check if d is a prime
		if isPrime(d) {
			// Check if A/d is a power of d
			if isPower(A/d, d) {
				count++
			}
		}
	}
	// Check if A itself is a prime (x = A-1)
	if isPrime(A) {
		count++
	}
	return count
}

func getDivisors(n int64) []int64 {
	var divisors []int64
	for i := int64(1); i*i <= n; i++ {
		if n%i == 0 {
			divisors = append(divisors, i)
			if i != n/i {
				divisors = append(divisors, n/i)
			}
		}
	}
	return divisors
}

func isPrime(n int64) bool {
	if n < 2 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	for i := int64(3); i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func isPower(n, base int64) bool {
	if n == 1 {
		return true
	}
	if base == 1 {
		return false
	}
	for n%base == 0 {
		n /= base
	}
	return n == 1
}
