	// Find all primes up to sqrt(max divisor)
	maxD := divisors[len(divisors)-1]
	sqrtMax := int64(1)
	for sqrtMax*sqrtMax <= maxD {
		sqrtMax++
	}
	sqrtMax--

	isPrime := make([]bool, sqrtMax+1)
	for i := range isPrime {
		isPrime[i] = true
	}
	isPrime[0] = false
	isPrime[1] = false
	for i := int64(2); i*i <= sqrtMax; i++ {
		if isPrime[i] {
			for j := i * i; j <= sqrtMax; j += i {
				isPrime[j] = false
			}
		}
	}

	// For each divisor d of A, check if d-1 is prime
	count := 0
	for _, d := range divisors {
		if d == 1 {
			continue
		}
		n := d - 1
		if n <= 1 {
			continue
		}
		if n <= sqrtMax {
			if isPrime[n] {
				count++
			}
		} else {
			// Check if n is prime by trial division up to sqrt(n)
			isNPrime := true
			for i := int64(2); i*i <= n; i++ {
				if n%i == 0 {
					isNPrime = false
					break
				}
			}
			if isNPrime {
				count++
			}
		}
	}

	fmt.Println(count)
