package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var A int64
	fmt.Fscan(in, &A)

	// Generate all divisors of A
	divisors := make([]int64, 0)
	for i := int64(1); i*i <= A; i++ {
		if A%i == 0 {
			divisors = append(divisors, i)
			if i != A/i {
				divisors = append(divisors, A/i)
			}
		}
	}

	// Sort divisors
	for i := 0; i < len(divisors); i++ {
		for j := i + 1; j < len(divisors); j++ {
			if divisors[i] > divisors[j] {
				divisors[i], divisors[j] = divisors[j], divisors[i]
			}
		}
	}

	// Compute sigma for each divisor
	sigmaMap := make(map[int64]int64)
	for _, d := range divisors {
		var s int64
		for i := int64(1); i*i <= d; i++ {
			if d%i == 0 {
				s += i
				if i != d/i {
					s += d / i
				}
			}
		}
		sigmaMap[d] = s
	}

	// Count valid x
	count := 0
	for _, d := range divisors {
		if sigmaMap[d] == A {
			count++
		}
	}

	fmt.Println(count)
}
